function prime_fib(n) {
  let fib = [0, 1];
  let count = 0;

  while (true) {
    const nextFib = fib[fib.length - 1] + fib[fib.length - 2];
    fib.push(nextFib);

    if (isPrime(nextFib)) {
      count++;
      if (count === n) {
        return nextFib;
      }
    }
  }
}

function isPrime(num) {
  if (num <= 1) return false;
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) return false;
  }
  return true;
}
